import * as fs from 'node:fs/promises';
import {mock} from 'node:test';
import {AsyncLocalStorage} from 'node:async_hooks';
import {spawn} from 'node:child_process';
const base='/tmp/codex-tool-runs/svton/m2-r2-review-20260930';
const dir=await fs.mkdtemp(base+'/prev-race-'),file=dir+'/state.json',lock=file+'.lock';
const child=spawn(process.execPath,['-e','process.exit(0)']);await new Promise(r=>child.on('exit',r));
try{process.kill(child.pid,0);throw Error('fixture PID reused')}catch(e){if(e.code!=='ESRCH')throw e;}
await fs.writeFile(lock,`${child.pid}\tdead-owner-token\n`);
const defer=()=>{let resolve;const promise=new Promise(r=>resolve=r);return {promise,resolve}};
const paused=defer(),resume=defer(),bEntered=defer(),releaseB=defer(),aEntered=defer(),releaseA=defer();
const actor=new AsyncLocalStorage();let hooked=false,active=0,maxActive=0,bActive=false;
let aOverwroteLiveB=false;
const {default:ignored,...named}=fs;
mock.module('node:fs/promises',{namedExports:{...named,rename:async(from,to)=>{
 if(actor.getStore()==='A'&&to===lock&&!hooked){hooked=true;paused.resolve();await resume.promise;aOverwroteLiveB=bActive;}
 return fs.rename(from,to);
}}});
const {withFileLock}=await import('/Users/zhaoxingbo/Workspace/ai-driven/svton/shipkit/dist/shared/file-lock.js');
const a=actor.run('A',()=>withFileLock(file,async()=>{active++;maxActive=Math.max(active,maxActive);aEntered.resolve();await releaseA.promise;active--;},{timeoutMs:5000}));
await paused.promise;
const prevStat=await fs.stat(lock+'.prev'),lockStat=await fs.stat(lock);
// A is alive and holds prev. A scheduling pause exceeds PREV_RESIDUE_MS.
await new Promise(r=>setTimeout(r,650));
const b=actor.run('B',()=>withFileLock(file,async()=>{bActive=true;active++;maxActive=Math.max(active,maxActive);bEntered.resolve();await releaseB.promise;active--;bActive=false;},{timeoutMs:3000}));
await bEntered.promise;
resume.resolve();await aEntered.promise;
const result={maxActive,aOverwroteLiveB,activeAtObservation:active,pausedMs:650,prevAndLockSameInode:prevStat.ino===lockStat.ino,prevMtimeEqualsLockMtime:prevStat.mtimeMs===lockStat.mtimeMs,onlySchedulingMocked:true};
releaseA.resolve();await a;releaseB.resolve();await b;
await fs.writeFile(base+'/prev-race-results.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result));mock.restoreAll();

